==Passives==
===Stun immunity===
{{Query passive skills
|where=
  passive_skill_stats.id LIKE "%cannot_be_stunned%"
  OR passive_skill_stats.id LIKE "%immune_to_stun%"
}}

===Reflect immunity===
{{Query passive skills
|where=
  passive_skill_stats.id LIKE "%cannot_take_reflected%damage%"
  OR passive_skill_stats.id LIKE "%cannot_be_reflected%"
}}

===All elemental ailment immunity===
{{Query passive skills
|where=
  passive_skill_stats.id LIKE "%immune_to_elemental%ailments%"
  OR passive_skill_stats.id LIKE "%immune_to_status_ailments%"
}}

===Other ailment immunity===
{{Query passive skills
|where=
  (
    passive_skill_stats.id LIKE "%cannot%"
    OR passive_skill_stats.id LIKE "%immune%"
  )
  AND 
  (
    passive_skill_stats.id LIKE "%chill%"
    OR passive_skill_stats.id LIKE "%shock%"
    OR passive_skill_stats.id LIKE "%bleed%"
    OR passive_skill_stats.id LIKE "%ignite%"
    OR passive_skill_stats.id LIKE "%freeze%"
    OR passive_skill_stats.id LIKE "%poison%"
  )
}}

===Other passives===
{{Query passive skills
|where=
  (
    passive_skill_stats.id LIKE "%cannot%"
    OR passive_skill_stats.id LIKE "%immune%"
  )
  AND passive_skill_stats.id NOT LIKE "%cannot_be_stunned%"
  AND passive_skill_stats.id NOT LIKE "%immune_to_stun%"
  AND passive_skill_stats.id NOT LIKE "%cannot_take_reflected%damage%"
  AND passive_skill_stats.id NOT LIKE "%cannot_be_reflected%"
  AND passive_skill_stats.id NOT LIKE "%immune_to_%elemental%ailments%"
  AND passive_skill_stats.id NOT LIKE "%chill%"
  AND passive_skill_stats.id NOT LIKE "%shock%"
  AND passive_skill_stats.id NOT LIKE "%bleed%"
  AND passive_skill_stats.id NOT LIKE "%ignite%"
  AND passive_skill_stats.id NOT LIKE "%freeze%"
  AND passive_skill_stats.id NOT LIKE "%poison%"
  AND passive_skill_stats.id NOT LIKE "%immune_to_status_ailments%"
  AND passive_skill_stats.id NOT IN ("enemies_taunted_by_you_cannot_evade_attacks", "guardian_nearby_enemies_cannot_gain_charges")
}}

===Keystones===
{{Query keystone passive skills
|where=
  (
    passive_skills.id NOT LIKE "%atlas%"
    AND passive_skills.name NOT LIKE "%POWER CHARGE%"
    AND passive_skills.stat_text LIKE "%cannot%"
    OR passive_skills.stat_text LIKE "%immune%"
  )
}}

